create or replace function public.is_community_member(p_community_id uuid,p_user_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.community_members cm where cm.community_id=p_community_id and cm.user_id=p_user_id) $$;
create or replace function public.is_conversation_member(p_conversation_id uuid,p_user_id uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.conversation_members cm where cm.conversation_id=p_conversation_id and cm.user_id=p_user_id) $$;
grant execute on function public.is_community_member(uuid,uuid) to anon,authenticated;
grant execute on function public.is_conversation_member(uuid,uuid) to authenticated;
drop policy communities_read on public.communities;
create policy communities_read on public.communities for select using (visibility='public' or owner_id=(select auth.uid()) or public.is_community_member(id,(select auth.uid())));
drop policy community_members_read on public.community_members;
create policy community_members_read on public.community_members for select using (user_id=(select auth.uid()) or public.is_community_member(community_id,(select auth.uid())));
drop policy conversations_read_member on public.conversations;
create policy conversations_read_member on public.conversations for select to authenticated using (public.is_conversation_member(id,(select auth.uid())));
drop policy conversation_members_read_self on public.conversation_members;
create policy conversation_members_read_self on public.conversation_members for select to authenticated using (public.is_conversation_member(conversation_id,(select auth.uid())));
drop policy conversation_members_insert_creator on public.conversation_members;
create policy conversation_members_insert_creator on public.conversation_members for insert to authenticated with check (exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=(select auth.uid())) or user_id=(select auth.uid()));
drop policy messages_read_member on public.messages;
create policy messages_read_member on public.messages for select to authenticated using (public.is_conversation_member(conversation_id,(select auth.uid())));
drop policy messages_insert_member on public.messages;
create policy messages_insert_member on public.messages for insert to authenticated with check (sender_id=(select auth.uid()) and public.is_conversation_member(conversation_id,(select auth.uid())));
create or replace function public.add_community_owner() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.community_members(community_id,user_id,role) values(new.id,new.owner_id,'owner') on conflict do nothing; return new; end; $$;
create trigger on_community_created_add_owner after insert on public.communities for each row execute function public.add_community_owner();
create or replace function public.add_conversation_creator() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.conversation_members(conversation_id,user_id,role) values(new.id,new.created_by,'owner') on conflict do nothing; return new; end; $$;
create trigger on_conversation_created_add_creator after insert on public.conversations for each row execute function public.add_conversation_creator();
